"""Require actual passes for the licensed solver and MNIST acceptance cases."""

import argparse
from pathlib import Path
import xml.etree.ElementTree as ET


LICENSED_CASES = {
    ("tests.test_equilibrium_propagation.TestKaiwuAnnealer", name)
    for name in ("test_annealer_finds_the_minimum", "test_two_phase_energy_history")
}
MNIST_CASES = {
    ("tests.test_ep_mnist", name)
    for name in (
        "test_training_and_checkpoint_evaluation[False]",
        "test_training_and_checkpoint_evaluation[True]",
        "test_invalid_arguments_create_no_output[--epochs-0]",
        "test_invalid_arguments_create_no_output[--batch-size--1]",
        "test_invalid_arguments_create_no_output[--beta-nan]",
        "test_invalid_arguments_create_no_output[--lr-inf]",
        "test_invalid_arguments_create_no_output[--input-scale-0]",
        "test_invalid_arguments_create_no_output[--split-seed--1]",
        "test_training_refuses_existing_output",
    )
}


def validate_results(path, *, licensed=False, mnist=False):
    """Reject missing, skipped, duplicated or unsuccessful acceptance cases."""
    cases = ET.parse(path).findall(".//testcase")
    if not cases:
        raise ValueError("JUnit contains no test cases")
    if any(case.find("failure") is not None or case.find("error") is not None
           for case in cases):
        raise ValueError("JUnit contains failed tests or setup errors")
    required = (LICENSED_CASES if licensed else set()) | (MNIST_CASES if mnist else set())
    for classname, name in sorted(required):
        matches = [case for case in cases
                   if (case.get("classname"), case.get("name")) == (classname, name)]
        if len(matches) != 1 or matches[0].find("skipped") is not None:
            raise ValueError(f"Required case did not pass exactly once: {classname}::{name}")
    return len(required)


def main():
    """Validate the JUnit report generated by this matrix job."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("report", type=Path)
    parser.add_argument("--licensed", action="store_true")
    parser.add_argument("--mnist", action="store_true")
    args = parser.parse_args()
    count = validate_results(args.report, licensed=args.licensed, mnist=args.mnist)
    print(f"Acceptance verified: {count} required cases passed.")


if __name__ == "__main__":
    main()
